static void store_xor8(__m256i w[16], uint8_t *out, const uint8_t *in) {
    /* Interleave 32-bit lanes into 64-bit pairs, then 128, then 256. */
    /* Step 1: interleave word pairs within 128-bit lanes: (0,1), (2,3), ... */
    __m256i t0 = _mm256_unpacklo_epi32(w[0], w[1]);
