    EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);

    unsigned char my_nonce[12];
    memcpy(my_nonce, nonce, 12);
    my_nonce[0] = (unsigned char)id;

    int seen = 0;
    while (1) {
        pthread_mutex_lock(&mu);
        while (epoch == seen && !stop) pthread_cond_wait(&cv, &mu);
        int my_epoch = epoch;
        int my_stop = stop;
        pthread_mutex_unlock(&mu);
        if (my_stop) break;
        seen = my_epoch;

        size_t chunk = (N / THREADS) & ~63ull;
        size_t start = id * chunk;
        size_t len = (id == THREADS - 1) ? (N - start) : chunk;
        unsigned char *p = buf + start;
