        run_once(); /* warmup */
        double t0 = now();
        int iters = 4;
        for (int k = 0; k < iters; k++) run_once();
        double dt = (now() - t0) / iters;
        pthread_mutex_lock(&mu);
        stop = 1;
        pthread_cond_broadcast(&cv);
        pthread_mutex_unlock(&mu);
        for (int i = 0; i < th; i++) pthread_join(ts[i], NULL);
        printf("threads %d: %.4fs  %.0f MB/s\n", th, dt, (N/1e6)/dt);
