static unsigned char *buf;
static size_t N;
static int THREADS;
static unsigned char key[32];

typedef struct { int id; int iters; } Arg;

static double now() { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return t.tv_sec + t.tv_nsec/1e9; }

static void *worker(void *vp) {
    Arg *a = vp;
    int id = a->id;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    unsigned char nonce[12] = {0};
    nonce[0] = (unsigned char)id;
    size_t chunk = (N / THREADS) & ~63ull;
    size_t start = id * chunk;
    size_t len = (id == THREADS - 1) ? (N - start) : chunk;
    unsigned char *p = buf + start;
    for (int k = 0; k < a->iters; k++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        int outl = 0;
        EVP_EncryptUpdate(ctx, p, &outl, p, (int)len);
        unsigned char fin[16];
        EVP_EncryptFinal_ex(ctx, fin, &outl);
        unsigned char tag[16];
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

static void bench(int th, int iters) {
    THREADS = th;
    pthread_t ts[8];
    Arg args[8];
    double t0 = now();
    for (int i = 0; i < th; i++) { args[i].id = i; args[i].iters = iters; pthread_create(&ts[i], NULL, worker, &args[i]); }
    for (int i = 0; i < th; i++) pthread_join(ts[i], NULL);
    double dt = (now() - t0) / iters;
    printf("threads %d: %.4fs  %.0f MB/s\n", th, dt, (N/1e6)/dt);
    fflush(stdout);
}

int main() {
    N = 40ull * 1024 * 1024;
    buf = aligned_alloc(64, N);
    memset(buf, 1, N);
    memset(key, 0x11, 32);
    for (int th = 1; th <= 6; th++) bench(th, 3);
    return 0;
}
