#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <immintrin.h>
static double now() { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return t.tv_sec + t.tv_nsec/1e9; }
int main() {
    size_t sizes[] = {40ull<<20, 128ull<<20, 512ull<<20};
    for (int s = 0; s < 3; s++) {
        size_t N = sizes[s];
        uint8_t *a = aligned_alloc(64, N);
        uint8_t *b = aligned_alloc(64, N);
        if (!a || !b) { printf("alloc fail\n"); return 1; }
        memset(a, 1, N);
        memset(b, 2, N);
        /* single pass timing, repeated */
        double best = 1e9;
        for (int i = 0; i < 5; i++) {
            double t0 = now();
            memcpy(b, a, N);
            double dt = now()-t0;
            if (dt < best) best = dt;
            a[0] = b[N-1]; /* keep live */
        }
        printf("memcpy %4zuMB: best %.4fs  copy %.1f GB/s  bus %.1f GB/s\n", N>>20, best, (N/1e9)/best, (2.0*N/1e9)/best);

        /* read-modify-write (xor) like a cipher: read a, write b */
        best = 1e9;
        for (int rep = 0; rep < 3; rep++) {
            double t0 = now();
            for (size_t i = 0; i + 32 <= N; i += 32) {
                __m256i v = _mm256_loadu_si256((const __m256i*)(a+i));
                v = _mm256_xor_si256(v, _mm256_set1_epi32(0x12345678));
                _mm256_storeu_si256((__m256i*)(b+i), v);
            }
            double dt = now()-t0;
            if (dt < best) best = dt;
        }
        printf("xor    %4zuMB: best %.4fs  payload %.1f GB/s  bus %.1f GB/s\n", N>>20, best, (N/1e9)/best, (2.0*N/1e9)/best);
        free(a); free(b);
    }
    return 0;
}
